function eventForm(){
 if(!state.me)return empty('ログインしてイベントをつくりましょう')+'<button class="primary" data-auth>ログイン / 登録</button>';
 const published=event(selected),draft=state.drafts?.find(d=>d.id===selected),e=published||draft?.data;if(published&&published.owner!==state.me.id&&!published.extra?.can_edit)return empty('このイベントを編集する権限がありません');
 const dt=s=>{const d=s?new Date(s):new Date(Date.now()+86400000);return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};
 const option=(value,label,selected)=>'<option value="'+value+'" '+(value===selected?'selected':'')+'>'+label+'</option>';
 return heading('HOST',published?'イベントを編集。':draft?'下書きを仕上げる。':'イベントをつくる。')+
 `<section class="cx-paper"><h2>下書き</h2>${(state.drafts||[]).map(d=>`<p><a data-nav href="${route('create',d.id)}">${esc(d.data.name||'無題の下書き')}</a> · ${esc(fmt(d.at*1000))} <button class="outline" data-delete-draft="${esc(d.id)}">削除</button></p>`).join('')||'<p class="cx-muted">下書きはありません。</p>'}</section>`+
 '<section class="cx-paper"><form class="cx-form" data-form="event" data-id="'+esc(published?.id||'')+'" data-draft-id="'+esc(draft?.id||'')+'">'+
 (!published?'<label class="rf-check"><input type="checkbox" name="demo" '+(e?.demo?'checked':'')+'>撮影・操作体験用デモ（参加募集なし）</label>':'')+
 '<label>イベント名<input name="name" required maxlength="100" value="'+esc(e?.name||'')+'"></label>'+
 '<div class="cx-form-row"><label>場所の名前<input name="place" required maxlength="100" value="'+esc(e?.place||'')+'"></label><label>カテゴリー<input name="kind" required maxlength="60" value="'+esc(e?.kind||'')+'" placeholder="例：街歩き・写真・音楽"></label></div>'+
 '<label>イベントの説明<textarea name="description" required maxlength="3000">'+esc(e?.description||'')+'</textarea></label>'+
 '<div class="cx-form-row"><label>開始（'+esc(displayZone())+'）<input type="datetime-local" name="start" required value="'+dt(e?.start)+'"></label><label>終了<input type="datetime-local" name="end" required value="'+dt(e?.end||new Date(Date.now()+90000000).toISOString())+'"></label></div>'+
 '<label>会場住所（建物名も）<input name="address" maxlength="240" value="'+esc(e?.address||'')+'" placeholder="建物名・番地など"></label>'+
 '<label>集合場所<input name="meeting" maxlength="240" value="'+esc(e?.meeting||'')+'" placeholder="例：公園の北入口"></label>'+
 '<div class="cx-event-picker-tools"><button type="button" class="outline" data-picker-city="tokyo">東京周辺</button><button type="button" class="outline" data-picker-city="aichi">愛知周辺</button><button type="button" class="outline" data-picker-map>Googleマップで会場を選ぶ</button></div><p class="cx-event-picker-status" id="cx-picker-status">地図を確認して会場の入口・集合地点を指定してください。</p><div id="cx-event-picker" role="img" aria-label="会場位置の選択地図"></div>'+
 '<div class="cx-form-row"><label>緯度<input type="number" name="lat" min="-90" max="90" step="any" required value="'+(e?.lat??'')+'"></label><label>経度<input type="number" name="lon" min="-180" max="180" step="any" required value="'+(e?.lon??'')+'"></label></div>'+
 '<label>位置の種別<select name="location_precision">'+option('approximate','公園・施設の代表点',e?.location_precision)+option('entrance','利用できる入口',e?.location_precision)+option('meeting','集合場所',e?.location_precision)+'</select></label>'+
 '<div class="cx-form-row"><label>フロア（例：B2・3F）<input type="text" name="floor" pattern="[Bb]?[0-9]{1,3}[Ff]?|-?[0-9]{1,3}" value="'+(e?.floor??'')+'"></label><label>入口から会場までの案内<textarea name="entrance" maxlength="600">'+esc(e?.entrance||'')+'</textarea></label></div>'+
 '<input type="hidden" name="venue_rights" value="">'+
 '<input type="hidden" name="location_confirmed" value="">'+
 '<label><input type="checkbox" name="indoor" '+(e?.indoor?'checked':'')+'>主な会場は屋内</label>'+
 '<label>必要な持ち物・服装の条件<textarea name="bring" maxlength="300">'+esc(e?.bring||'')+'</textarea></label>'+
 '<fieldset><legend>料金と参加条件</legend><div class="cx-form-row"><label>料金（税込・円、無料は0）<input type="number" name="price_yen" min="0" max="1000000" step="1" value="'+esc(e?.price_yen??'')+'" placeholder="未定なら空欄"></label><label>対象年齢の下限（任意）<input type="number" name="age_min" min="0" max="120" step="1" value="'+esc(e?.age_min??'')+'"></label></div><label>参加条件<textarea name="eligibility" maxlength="300">'+esc(e?.eligibility||'')+'</textarea></label><label><input type="checkbox" name="preregistration" '+(e?.preregistration?'checked':'')+'>別途事前登録が必要</label><p class="cx-muted">Joinは個人の予定であり、申込・席の確保ではありません。登録方法は説明欄に明記してください。</p><div class="cx-form-row"><label>無料イベントの予約定員（任意）<input type="number" name="capacity" min="1" max="1000" step="1" value="'+esc(e?.capacity??'')+'" placeholder="空欄ならアプリ内予約なし"></label><label>予約受付の締切（任意）<input type="datetime-local" name="booking_deadline" value="'+(e?.booking_deadline?dt(e.booking_deadline):'')+'"></label></div><p class="cx-muted">アプリ内の定員予約は料金0円のイベントだけです。満席時はキャンセル待ちになります。</p><label>主催者の外部予約URL（任意・HTTPS）<input type="url" name="booking_url" maxlength="500" value="'+esc(e?.booking_url||'')+'" placeholder="https://..."></label><label>支払先（有料なら必須）<input name="payment_recipient" maxlength="120" value="'+esc(e?.payment_recipient||'')+'"></label><label>返金・中止時の扱い（有料なら必須）<textarea name="refund_policy" maxlength="600">'+esc(e?.refund_policy||'')+'</textarea></label></fieldset>'+ 
 '<fieldset><legend>会場のバリアフリー情報（確認できた項目のみ）</legend><label><input type="checkbox" name="step_free" '+(e?.step_free?'checked':'')+'>段差のない経路</label><label><input type="checkbox" name="elevator" '+(e?.elevator?'checked':'')+'>エレベーターあり</label><label><input type="checkbox" name="wheelchair" '+(e?.wheelchair?'checked':'')+'>車椅子で利用できると主催者が確認</label></fieldset>'+ 
 '<label>状態<select name="status">'+option('active','開催予定',e?.status)+option('canceled','中止',e?.status)+'</select></label>'+
 '<label>中止理由（中止時に必須）<textarea name="cancel_reason" maxlength="500">'+esc(e?.cancel_reason||'')+'</textarea></label>'+
 '<div class="cx-actions">'+(published?'':'<button type="button" class="outline" data-save-draft>下書きを保存</button>')+'<button class="primary">内容を確認して'+(published?'更新':'公開')+'する →</button></div><p data-form-error role="alert"></p></form></section>';
}
function eventPreview(data){pendingEvent=data;const visual=data.completion_options?.cover??event(data.id)?.extra?.cover,visualAlt=data.completion_options?.cover_alt||event(data.id)?.extra?.cover_alt||'';const mapUrl='https://www.google.com/maps?q='+encodeURIComponent(data.lat+','+data.lon);dialog(`<h2>公開前プレビュー</h2><p class="cx-muted">利用者に見える主要情報です。住所とピンの一致を地図でもう一度確認してください。</p><section class="cx-paper">${visual?`<div class="cx-event-visual"><img src="${esc(visual)}" alt="${esc(visualAlt)}"></div>`:""}<h3>${esc(data.name)}</h3><p>${esc(dateRange(data))}</p><p>⌖ ${esc(data.place)} · ${esc(data.address||'住所未登録')} · ${esc(data.meeting||'集合場所未登録')}</p><p>${esc(data.description)}</p><p>${esc(priceLabel(data))}${data.age_min!=null?' · '+data.age_min+'歳以上':''}${data.preregistration?' · 別途事前登録が必要':''}</p><p>${esc(data.eligibility||'参加条件の指定なし')}</p><p>${data.capacity?'無料予約定員 '+esc(data.capacity)+'人':''}${data.booking_deadline?' · 受付締切 '+esc(fmt(data.booking_deadline,{year:'numeric'})):''}${data.booking_url?' · 外部予約URLあり':''}</p><p>位置：${esc(data.lat)}, ${esc(data.lon)}（${esc(data.location_precision)}）</p><a class="outline" href="${mapUrl}" target="_blank" rel="noopener">選んだピンを地図で再確認 ↗</a></section><p>Joinは予定の記録です。席の確保や予約ではありません。${data.price_yen>0?'支払いはアプリ外で主催者に確認してください。':''}</p><label class="rf-publish-confirm"><input id="rf-publish-confirm" type="checkbox">日時・会場の利用条件・公開内容を確認しました<span class="rf-required">*</span></label><div class="cx-actions"><button class="outline" data-back-event>入力へ戻る</button><button class="primary" data-confirm-event>${data.id?'更新を確定':'公開を確定'}</button></div><p id="cx-event-preview-error" role="alert"></p>`)}
function eventAutosaveKey(f){return 'spatial-host-autosave:'+state.me.id+':'+(f.dataset.id||f.dataset.draftId||'new')}
function saveEventAutosave(f){const fields={};for(const el of f.elements){if(!el.name||el.type==='file')continue;fields[el.name]=el.type==='checkbox'?el.checked:el.value;}try{sessionStorage.setItem(eventAutosaveKey(f),JSON.stringify(fields));}catch(_){}}
function restoreEventAutosave(){const f=document.querySelector('[data-form="event"]');if(!f||!state.me)return;try{const saved=JSON.parse(sessionStorage.getItem(eventAutosaveKey(f))||'null');if(!saved)return;for(const [name,value] of Object.entries(saved)){const el=f.elements.namedItem(name);if(!el||!('value'in el))continue;if(el.type==='checkbox')el.checked=Boolean(value);else el.value=String(value);}const note=document.createElement('p');note.className='cx-notice';note.textContent='このタブで作成中だった入力を復元しました。公開前に会場の地図を再確認してください。';f.prepend(note);}catch(_){}}
document.addEventListener('input',e=>{const f=e.target.closest?.('[data-form="event"]');if(f)saveEventAutosave(f)});
document.addEventListener('change',e=>{const f=e.target.closest?.('[data-form="event"]');if(f)saveEventAutosave(f)});
