function graphPage(){
 const people=normalPeople().sort((a,b)=>Number(b.id===state.me?.id)-Number(a.id===state.me?.id)||Number(state.following.includes(b.id))-Number(state.following.includes(a.id))||a.name.localeCompare(b.name)).slice(0,12);
 const events=normalEvents().filter(e=>people.some(p=>p.id===e.owner)).slice(0,24);
 const nodes=[...people.map((p,i)=>({id:p.id,x:130,y:70+i*85,label:p.name,avatar:p.avatar,kind:'profile'})),...events.map((e,i)=>({id:e.id,x:520,y:65+i*65,label:e.name,avatar:account(e.owner)?.avatar,kind:'event'}))];
 const h=Math.max(380,people.length*85+80,events.length*65+80);
 const svg=`<div class="cx-graph-canvas"><svg id="cx-graph-svg" width="780" height="${h}" viewBox="0 0 780 ${h}" role="img" aria-label="主催者とイベントのつながり">${events.map(e=>{const a=nodes.find(n=>n.id===e.owner),b=nodes.find(n=>n.id===e.id);return `<path d="M ${a.x} ${a.y} C 310 ${a.y},350 ${b.y},${b.x} ${b.y}" fill="none" stroke="#4c95c9" stroke-width="2"/>`}).join('')}${nodes.map((n,i)=>`<defs><clipPath id="rf-node-${i}"><circle cx="${n.x}" cy="${n.y}" r="${n.kind==='profile'?25:19}"/></clipPath></defs><a data-nav href="${route(n.kind,n.id)}" aria-label="${esc(n.label)}"><title>${esc(n.label)}</title><circle cx="${n.x}" cy="${n.y}" r="${n.kind==='profile'?27:21}" fill="white" stroke="${n.kind==='profile'?'#087bff':'#10a6bb'}" stroke-width="3"/><image href="${esc(n.avatar||'/owl-mark.svg')}" x="${n.x-(n.kind==='profile'?25:19)}" y="${n.y-(n.kind==='profile'?25:19)}" width="${n.kind==='profile'?50:38}" height="${n.kind==='profile'?50:38}" preserveAspectRatio="xMidYMid slice" clip-path="url(#rf-node-${i})"/></a>`).join('')}</svg></div>`;
 const textList=`<label>関係を検索 <input id="cx-graph-search" type="search" placeholder="主催者・イベント名"></label><div id="cx-graph-list">${people.map(p=>`<section data-graph-item data-search="${esc(p.name.toLowerCase())}"><h3><a data-nav href="${route('profile',p.id)}">${esc(p.name)}</a></h3>${events.filter(e=>e.owner===p.id).map(e=>`<p><a data-nav href="${route('event',e.id)}">${esc(e.name)}</a></p>`).join('')||'<p>この範囲に開催予定はありません。</p>'}</section>`).join('')||'<p>表示できる関係はありません。</p>'}</div>`;
 return heading('MEET','つながりから探す。','本人とLinked主催者に近い公開イベントを表示します。')+`<section class="cx-paper"><p>大きなアイコンは主催者、小さなアイコンはその人のイベント。線は主催の関係です。</p><div class="cx-actions"><button class="outline" data-graph-scale="-1">縮小</button><button class="outline" data-graph-scale="1">拡大</button></div>${svg}</section><section class="cx-paper"><h2>関係一覧</h2>${textList}</section>`;
}
function glassesPage(){const e=event(selected)||state.events[0];return heading('SPATIAL GLASSES / SIMULATION','視界に、次の発見を。','スマートグラスの操作シミュレーションです。カメラ映像・実測ARではありません。')+`<section class="cx-glasses"><div class="cx-glasses-top"><b>SPATIAL LENS</b><span>SIMULATION · ${new Date().toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit'})}</span></div><div class="cx-lens-reticle">＋</div><a class="cx-lens-anchor" data-nav href="${route('event',e.id)}"><span>⌖ Watch体験</span><h2>${esc(e.name)}</h2><p>${esc(e.place)} · 一致度 ${e.fit.score}%</p><b>つまむ / 選択する →</b></a><div class="cx-lens-bottom">${state.events.slice(0,5).map(x=>`<a data-nav href="${route('glasses',x.id)}" class="${x.id===e.id?'active':''}">${esc(x.name)}</a>`).join('')}</div></section><p class="cx-muted">カードを選んで視界を切替。ぽよから音声・テキストで提案を受け、実行する操作は自分で選びます。</p>`;}
