function mapPage(){return SpatialExplore.page();}
function render(){epoch++;clearInterval(threadTimer);mapController?.stop();mapController=null;const p=new URLSearchParams(location.search);view=p.get('view')||'home';if(view==='demo'){view='discover';p.set('view','discover');p.set('tab','all');history.replaceState({},'','/?'+p.toString());}selected=p.get('id')||'';if(p.has('q'))$('#cx-search').value=p.get('q');if(view==='discover'){recommendMode=['all','you','linked','near'].includes(p.get('tab'))?p.get('tab'):'all';searchTab=['events','spots','people'].includes(p.get('target'))?p.get('target'):'events';}if(view==='discover')findFilters.host=account(selected)?selected:'';if(view==='event')recordHistory(selected);if(view==='map'&&selected)recordHistory(selected,'map');ui.shell();$('#cx-main').innerHTML=view==='home'?ui.home():view==='settings'?ui.settings():view==='event'?detail(event(selected)):view==='profile'?profile(selected):view==='calendar'?calendar():view==='messages'?messages():view==='alerts'?alertsPage():view==='create'?eventForm():view==='map'?mapPage():view==='graph'?graphPage():view==='glasses'?mapPage():view==='people'?peoplePage():view==='watch'?watchPage():view==='venue'?venuePage(selected):discover();if(view==='event'&&event(selected)){loadThread('event',selected,'#cx-event-posts');if(event(selected)?.extra?.mode==='online')$('#cx-weather').textContent='オンライン開催のため会場の天気は表示しません。';else loadWeather(selected);}if(view==='messages'){const r=state.rooms.find(r=>r.id===selected)||(!selected?inbox.firstRoom():null);if(r){loadThread('room',r.id,'#cx-room-thread');threadTimer=setInterval(()=>{if(!document.hidden)loadThread('room',r.id,'#cx-room-thread',true)},15000);}}if(view==='map'||view==='glasses')setupMap();if(view==='people')filterPeople();if(view==='create'){setupEventPicker();restoreEventAutosave();}if(view==='discover'){filterCards($('#cx-search').value,activeKind);}updateSuggestions();document.title=(view==='event'?event(selected)?.name||'イベント':view==='home'?'気になる体験':view==='settings'?'設定':nav.find(n=>n[0]===view)?.[2]||'Spatial')+' — Spatial';proactive();completion.enhance();refine.enhance();refreshEventStates();}
let resultPage=0,resultKey='';const resultPageSize=24;
function filterCards(query,kind=activeKind){const key=JSON.stringify([query,kind,findFilters,recommendMode,searchTab,nearPosition]);if(key!==resultKey){resultPage=0;resultKey=key;}activeKind=kind;const q=(query||'').trim().toLowerCase(),now=new Date(),endToday=new Date(now);endToday.setHours(24,0,0,0);const saturday=new Date(now);saturday.setDate(now.getDate()+(now.getDay()===0?-1:(6-now.getDay()+7)%7));saturday.setHours(0,0,0,0);const monday=new Date(saturday);monday.setDate(saturday.getDate()+2);const events=normalEvents().filter(e=>{if((findFilters.near||recommendMode==='near')&&e.extra?.mode==='online')return false;if(recommendMode==='linked'&&!state.following.includes(e.owner))return false;if(recommendMode==='near'&&(!nearPosition||SpatialExplore.distance(nearPosition,e)>5000))return false;if(kind!=='すべて'&&e.kind!==kind)return false;if(findFilters.host&&e.owner!==findFilters.host)return false;if(findFilters.region&&!(e.place+' '+(e.address||'')).toLowerCase().includes(findFilters.region.replace(/[都府県]$/,'').toLowerCase()))return false;if(findFilters.mode!=='all'&&(e.extra?.mode||'onsite')!==findFilters.mode)return false;if(!refine.languageMatch(e.extra?.languages,findFilters.language))return false;if(findFilters.budget!==''&&(e.price_yen==null||e.price_yen>Number(findFilters.budget)))return false;if(findFilters.price==='free'&&e.price_yen!==0)return false;if(findFilters.price==='paid'&&!(e.price_yen>0))return false;if(findFilters.wheelchair&&!e.wheelchair)return false;if(findFilters.date){const day=new Date(findFilters.date+'T00:00:00'),next=new Date(day);next.setDate(day.getDate()+1);if(!(new Date(e.start)<next&&new Date(e.end)>day))return false;}if(q&&!(e.name+' '+e.place+' '+(e.address||'')+' '+e.description+' '+e.kind+' '+e.host?.name+' '+e.host?.handle+' '+(state.home_talks||[]).filter(p=>p.event_id===e.id).map(p=>p.body).join(' ')).toLowerCase().includes(q))return false;const start=new Date(e.start),end=new Date(e.end);if(findFilters.time==='today'&&!(start<endToday&&end>now))return false;if(findFilters.time==='weekend'&&!(start<monday&&end>saturday))return false;if(findFilters.indoor==='indoor'&&e.indoor!==true)return false;if(findFilters.indoor==='outdoor'&&e.indoor!==false)return false;if(findFilters.joinable&&(e.demo||e.status==='canceled'||end<=now))return false;if(findFilters.near&&(!nearPosition||SpatialExplore.distance(nearPosition,e)>5000))return false;return true}).sort((a,b)=>findFilters.sort==='new'?(b.created||0)-(a.created||0):findFilters.sort==='date'?Date.parse(a.start)-Date.parse(b.start):findFilters.sort==='distance'&&nearPosition?SpatialExplore.distance(nearPosition,a)-SpatialExplore.distance(nearPosition,b):recommendMode==='you'?(Number(b.fit.score)||0)-(Number(a.fit.score)||0)||Date.parse(a.start)-Date.parse(b.start):recommendMode==='near'?SpatialExplore.distance(nearPosition,a)-SpatialExplore.distance(nearPosition,b):Date.parse(a.start)-Date.parse(b.start));const spots=[...new Map(events.map(e=>[e.place,e])).values()];const people=normalPeople().filter(a=>!q||(a.name+' '+a.handle).toLowerCase().includes(q));const counts={events:events.length,spots:spots.length,people:people.length};document.querySelectorAll('[data-recommend]').forEach(b=>{b.setAttribute('aria-selected',String(recommendMode===b.dataset.recommend));b.tabIndex=recommendMode===b.dataset.recommend?0:-1;});document.querySelectorAll('[data-search-tab]').forEach(b=>{b.textContent=({events:'イベント',spots:'会場',people:'人'})[b.dataset.searchTab];b.setAttribute('aria-selected',String(searchTab===b.dataset.searchTab))});document.querySelectorAll('[data-category]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.category===kind)));document.querySelectorAll('[data-find-filter]').forEach(b=>{const id=b.dataset.findFilter;if(id==='clear'||id==='clear-time')return;b.setAttribute('aria-pressed',String(id==='today'||id==='weekend'?findFilters.time===id:id==='indoor'||id==='outdoor'?findFilters.indoor===id:findFilters[id]))});const items=searchTab==='events'?events:searchTab==='spots'?spots:people,pages=Math.max(1,Math.ceil(items.length/resultPageSize));resultPage=Math.min(resultPage,pages-1);const visible=items.slice(resultPage*resultPageSize,(resultPage+1)*resultPageSize);let html='';if(searchTab==='events')html=visible.map(card).join('');else if(searchTab==='spots')html=visible.map(e=>`<section class="cx-paper"><h3>${esc(e.place)}</h3><p>${esc(e.address||'住所はイベント詳細を確認してください')}</p><a class="outline" data-nav href="${route('venue',venueKey(e))}">この会場のイベント</a> <a class="outline" data-nav href="${route('map',e.id)}">地図で見る →</a></section>`).join('');else html=visible.map(a=>`<section class="cx-paper"><a data-nav href="${route('profile',a.id)}">${avatar(a)} <b>${esc(a.name)}</b><p>@${esc(a.handle)}</p></a></section>`).join('');$('#cx-cards').innerHTML=html||`<section class="cx-empty"><b>${q||kind!=='すべて'||findFilters.host||findFilters.time!=='all'||findFilters.date||findFilters.region||findFilters.price!=='all'||findFilters.wheelchair||findFilters.indoor!=='all'||findFilters.near?'条件に合う結果がありません':searchTab==='events'?(recommendMode==='linked'?'Linked主催者の開催予定はまだありません':recommendMode==='near'?'近く5kmに開催予定のイベントはありません':'開催予定のイベントはまだありません'):searchTab==='spots'?'該当するSpotsはまだありません':'該当する人はまだいません'}</b><p>条件を解除するか、期間を広げて探してください。</p><div class="cx-actions"><button class="outline" data-clear-find>条件を解除</button><button class="outline" data-find-filter="clear-time">期間を広げる</button><a class="outline" data-nav href="${route('map')}">Spotsを見る</a></div></section>`;if(recommendMode==='near'&&!nearPosition&&searchTab!=='people')$('#cx-cards').innerHTML='<section class="cx-empty"><h2>探す地域を選びましょう</h2><p>地域名を入力するか、現在地を使って近く5kmを探せます。</p><div class="cx-actions"><button class="outline" data-set-region>地域名を入力</button><button class="outline" data-find-filter="near">現在地を使う</button></div></section>';$('#cx-results-count').textContent=(recommendMode==='linked'?'Linked主催者 · ':recommendMode==='near'?'探索地点から5km · ':recommendMode==='all'?'すべて · ':'あなた向け · ')+counts[searchTab]+'件の'+({events:'イベント',spots:'Spots',people:'人'})[searchTab];const pager=$('#cx-result-pages');if(pager){pager.hidden=pages<=1;pager.innerHTML=pages>1?`<button data-result-page="-1" ${resultPage===0?'disabled':''} aria-label="前のページ">←</button><span>${resultPage+1} / ${pages}</span><button data-result-page="1" ${resultPage===pages-1?'disabled':''} aria-label="次のページ">→</button>`:'';}completion.searchEnhance();}
async function loadWeather(id){
 const ticket=epoch,host=$('#cx-weather');if(!host)return;
 try{
  const v=await request('/api/weather?id='+encodeURIComponent(id));
  if(ticket!==epoch||!host.isConnected)return;
  if(!v.available){host.textContent=v.reason;return;}
  const measures=[['気温',Number(v.temperature_c).toFixed(1),'℃'],['降水確率',v.rain_probability_pct==null?'—':Number(v.rain_probability_pct).toFixed(0),'%'],['風',v.wind_kmh==null?'—':Number(v.wind_kmh).toFixed(1),'km/h']];
  host.innerHTML=`<div class="rf-weather-top"><span>${esc(fmt(v.forecast_at*1000))}</span><span>${v.indoor?'屋内':'屋外'}</span></div><dl class="rf-weather-metrics">${measures.map(([label,value,unit])=>`<div><dt>${label}</dt><dd>${value}<small>${unit}</small></dd></div>`).join('')}</dl><ul class="rf-weather-preparation">${v.advice.map(a=>`<li>${esc(a)}</li>`).join('')}</ul><p class="rf-weather-source"><a href="https://open-meteo.com/en/docs" target="_blank" rel="noopener">Open-Meteo</a> · 取得 ${esc(new Date(v.fetched_at*1000).toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit'}))}</p><p class="rf-weather-caution">予報と現地の状況は異なる場合があります。</p>${state.me&&state.ai_available&&!event(id)?.demo&&completion.aiAllowed('ai_recommendation')?`<button class="rf-weather-ai" data-weather-ai="${esc(id)}"><img src="/poyo-owl.svg" width="24" height="24" alt="">AIで服装と準備を提案<span aria-hidden="true">↗</span></button><div id="cx-weather-ai" class="rf-weather-answer" role="status"></div>`:''}`;
 }catch{if(ticket===epoch&&host.isConnected)host.textContent='天気予報を取得できません。';}
}
async function suggestWeather(b){
  const ticket=epoch,host=$('#cx-weather-ai'),label=b.innerHTML;
  b.disabled=true;b.setAttribute('aria-busy','true');
  if(host){host.classList.remove('rf-weather-error');host.textContent='ぽよが考えています…';}
  try{const v=await request('/api/weather-advice',{id:b.dataset.weatherAi});if(ticket===epoch&&host?.isConnected){host.textContent=v.advice;b.innerHTML=label.replace(/AIで服装と準備を提案|もう一度提案する|再試行/,'もう一度提案する');}}
  catch(err){if(ticket===epoch&&host?.isConnected){host.classList.add('rf-weather-error');host.textContent=err.message;b.innerHTML=label.replace(/AIで服装と準備を提案|もう一度提案する|再試行/,'再試行');}}
  finally{b.disabled=false;b.removeAttribute('aria-busy');}
 }
async function loadThread(scope,id,target,quiet=false){const ticket=epoch;try{const v=await request('/api/thread?scope='+scope+'&id='+encodeURIComponent(id));if(ticket!==epoch||!$(target))return;const host=$(target),atBottom=host.scrollHeight-host.scrollTop-host.clientHeight<40;host.innerHTML=v.messages.map(p=>refine.talkHTML(p,scope)).join('')||'<p class="rf-chat-empty">最初のメッセージを送ってみましょう。</p>';completion.threadEnhance(host,v.messages,scope,id);if(scope==='room'&&(!quiet||atBottom))host.scrollTop=host.scrollHeight;if(scope==='room'){const room=state.rooms?.find(r=>r.id===id);if(room&&(room.unread||(v.messages.at(-1)?.id&&v.messages.at(-1).id!==room.latest_message_id))){await mutate('read_room',{id});if(ticket===epoch){inbox.refresh();const count=document.querySelector('.rf-chat-header small');if(count)count.textContent=(state.rooms.find(r=>r.id===id)?.member_count||1)+'人参加';}}}}catch(e){if(ticket===epoch&&$(target))$(target).textContent=e.message;}}
