function emergencyDialog(eventId=''){if(!needLogin())return;dialog(`<h2>安全・現地トラブルの連絡</h2><p>受付番号と状況をアカウントに保存します。担当者 @rynat の確認予定は毎日09:00〜21:00（日本時間）、2時間ごとです。即時確認は保証できません。差し迫った危険は現地の緊急機関へ連絡してください。</p><form class="cx-form" data-emergency-form data-event-id="${esc(eventId)}"><label>種類<select name="reason"><option value="danger">現地の危険</option><option value="harassment">嫌がらせ</option><option value="misinformation">危険な虚偽情報</option><option value="other">その他の安全問題</option></select></label><label>状況と必要な対応<textarea name="detail" required minlength="20" maxlength="1000" rows="5"></textarea></label><button class="primary">安全連絡を送信</button><p data-form-error role="alert"></p></form><h3>自分の連絡状況</h3>${(state.cases||[]).map(x=>`<p><code>${esc(x.id)}</code> · ${x.status==='open'?'受付済み・確認待ち':'対応記録済み'}${x.reviewed_at?` · ${esc(fmt(x.reviewed_at*1000))}`:''}</p>`).join('')||'<p>連絡履歴はありません。</p>'}`)}
