async function moderationDialog(){const data=await request('/api/moderation');dialog(`<h2>通報の確認</h2><p>危険な内容を優先し、対象と理由を確認して処理してください。緊急の危険は外部の緊急機関へ連絡してください。</p>${data.reports.map(r=>`<article class="cx-alert"><b>${esc(r.kind)} · ${esc(r.reason)} · ${esc(r.status)}</b><p>${esc(r.detail||'詳細なし')} · ${esc(fmt(r.at*1000))}</p><p>対象：${esc(r.target_name||r.target_body||'関連イベントなし')} ${r.target_author?`（投稿者ID: ${esc(r.target_author)}）`:''}</p><code>受付番号 ${esc(r.id)}</code>${r.review_note?`<p>対応記録：${esc(r.review_note)}</p>`:''}${r.status==='open'?`<div class="cx-actions">${['post','message'].includes(r.kind)?`<button class="outline" data-review="${esc(r.id)}" data-resolution="hidden">発言を非表示</button>`:''}${r.kind==='emergency'?`<button class="outline" data-review-emergency="${esc(r.id)}">対応を記録して終了</button>`:`<button class="outline" data-review="${esc(r.id)}" data-resolution="dismissed">確認して終了</button>`}</div>`:''}</article>`).join('')||'<p>通報はありません。</p>'}`);if(state.me?.google_only)SpatialIdentity.signin({request,reload,toast,mode:"link",onSuccess:()=>deleteAccountDialog()});}
