function authDialog(){dialog(`<section class="ui-auth"><img class="ui-auth-owl" src="/owl-mark.svg" alt=""><h2>おかえりなさい</h2><div class="ui-auth-tabs" role="group" aria-label="ログイン方法"><button type="button" data-auth-mode="login" aria-pressed="true">ログイン</button><button type="button" data-auth-mode="register" aria-pressed="false">新規登録</button></div><div id="ui-google-signin" class="ui-google-button"></div><div class="ui-auth-divider">または</div><form class="cx-form" data-form="auth"><input type="hidden" name="mode" value="login"><label>アカウントID<input name="handle" autocomplete="username" pattern="[a-zA-Z0-9_]{3,30}" required placeholder="あなたのID"></label><label id="ui-auth-name" hidden>表示名<input name="name" maxlength="60" placeholder="みんなに表示する名前"></label><label>パスワード<input name="password" type="password" autocomplete="current-password" minlength="12" maxlength="128" required placeholder="12文字以上"></label><button class="primary" type="submit">ログイン</button><p data-form-error role="alert"></p></form><p class="ui-auth-note">Googleで初めて利用すると、Spatialのアカウントを作成します。既存アカウントとの連携は設定から行えます。</p><p id="ui-google-error" role="alert"></p></section>`);SpatialIdentity.signin({request,reload,toast,mode:'login'});}
