document.addEventListener('change',e=>{if(e.target.id==='rf-recommend'){recommendMode=e.target.value;if(recommendMode==='all')findFilters.sort='date';if(recommendMode==='near'&&!nearPosition)nearPosition=SpatialExplore.offlineRegion(findFilters.region);history.replaceState({},'',route('discover')+'&tab='+recommendMode+'&target='+searchTab);filterCards($('#cx-search').value,activeKind);}});
document.addEventListener('pointerdown',e=>{const panel=$('#cx-poyo-panel'),bubble=$('#cx-bubble');if(!e.target.closest('#poyo-root,#sx-ar-hologram')){if(panel&&!panel.hidden)$('#poyo-toggle')?.click();if(bubble){bubble.hidden=true;savePref('spatial-poyo-dismissed','yes');}}if(!e.target.closest('.cx-side,.ui-nav-toggle')){document.body.classList.remove('ui-nav-open');document.querySelector('[data-ui-nav]')?.setAttribute('aria-expanded','false');}});

function profileDialog(){return refine.profileDialog();}
function notificationsDialog(){if(!needLogin())return;const n=state.me.notifications;dialog(`<h2>ちょうどいい、お知らせ。</h2><form class="cx-form" data-form="notifications"><label class="cx-check"><input type="checkbox" name="enabled" ${n.enabled?'checked':''}>参加イベントのリマインダー</label><label>イベント開始の何分前？<select name="minutes">${[[0,'開始時刻'],[5,'5分前'],[10,'10分前'],[30,'30分前'],[60,'1時間前'],[1440,'1日前']].map(([v,l])=>`<option value="${v}" ${n.minutes===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="cx-check"><input type="checkbox" name="messages" ${n.messages?'checked':''}>新しいトークのTalkをお知らせ</label><p class="cx-muted">アプリ内のお知らせは画面を開いている間に表示します。予定ファイルとGoogle APIで追加する予定にはリマインダー設定を含めます。端末が閉じていても通知したい場合はカレンダー側の通知を有効にしてください。</p><button class="outline" type="button" id="cx-browser-notifications">この端末のブラウザ通知を許可</button><button class="primary">設定を保存</button><p data-form-error role="alert"></p></form>`);$('#cx-browser-notifications').onclick=async()=>{if(!('Notification'in window)){toast('このブラウザでは利用できません');return;}toast(await Notification.requestPermission()==='granted'?'通知が許可されました':'通知は許可されていません');};}
function roomDialog(){if(!needLogin())return;const others=state.accounts.filter(a=>a.id!==state.me.id&&!a.sample&&!a.demo);dialog(`<h2>会話をはじめよう。</h2><form class="cx-form" data-form="room"><label>トーク名<input name="name" required maxlength="80" placeholder="例: 週末のアート散歩"></label><label>メンバーを検索<input id="cx-member-search" type="search" placeholder="名前・IDで探す"></label><fieldset><legend>招待する人（作成者を含め最大9人）</legend>${others.map(a=>`<label data-member-option><input type="checkbox" name="member" value="${a.id}">${esc(a.name)} @${esc(a.handle)}</label>`).join('')||'<p class="cx-muted">まだ他の登録者がいません。相手がアカウントを登録すると選べます。</p>'}</fieldset><p id="cx-member-selected" class="cx-muted">選択中：なし</p><p class="cx-muted">2人ならDM、3人以上ならグループです。招待された人が承認するまで会話は届きません。</p><button class="primary">招待を送る</button><p data-form-error role="alert"></p></form>`);}
async function uploadFile(file){if(!file||!file.size)return '';if(file.size>12_000_000)throw Error('写真は12MB以下にしてください');const bitmap=await createImageBitmap(file);const scale=Math.min(1,1100/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const data=canvas.toDataURL('image/jpeg',.78).split(',')[1];return (await request('/api/upload',{data})).url;}
document.addEventListener('submit',async e=>{const f=e.target.closest('[data-form]');if(!f)return;e.preventDefault();const type=f.dataset.form,fd=new FormData(f),button=f.querySelector('button[type=submit],button.primary');if(button)button.disabled=true;try{if(type==='report'){await mutate('report',{id:f.dataset.id,kind:f.dataset.kind,reason:fd.get('reason'),detail:fd.get('detail')});$('#cx-dialog').close();toast('通報を受け付けました');}else if(type==='notice'){await mutate('notice',{id:f.dataset.id,body:fd.get('body')});render();toast('お知らせを公開しました');}else if(type==='edit-notice'){await mutate('edit_notice',{id:f.dataset.id,event_id:f.dataset.eventId,body:fd.get('body')});$('#cx-dialog').close();render();toast('訂正を公開しました');}else if(type==='auth'){await request('/api/auth',Object.fromEntries(fd));$('#cx-dialog').close();await reload();toast('Spatialへようこそ。');}else if(type==='profile'){const data={name:fd.get('name'),bio:fd.get('bio'),theme:fd.get('theme'),layout:fd.get('layout'),interests:state.me.interests||[]};const img=await uploadFile(await refine.avatarFile(f));if(img)data.avatar=img;const banner=await uploadFile(await SpatialImages.file(f.elements.banner_file));if(banner)data.banner=banner;if(fd.get('remove_banner')==='on')data.banner='';data.banner_alt=fd.get('banner_alt')||'';await mutate('profile',data);$('#cx-dialog').close();go('profile');toast('プロフィールを更新しました');}else if(type==='notifications'){await mutate('notifications',{enabled:fd.get('enabled')==='on',minutes:Number(fd.get('minutes')),messages:fd.get('messages')==='on'});$('#cx-dialog').close();toast('Alerts設定を保存しました');}else if(type==='room'){const r=await mutate('room',{name:fd.get('name'),members:fd.getAll('member')});$('#cx-dialog').close();go('messages',r.id);}else if(type==='event'){if(f.dataset.online!=='true'&&f.dataset.mapReviewed!=='yes'){f.querySelector('[data-form-error]').textContent='地図で会場のピンを確認してから公開前プレビューへ進んでください。';f.querySelector('[data-picker-map]').focus();return;}const data=Object.fromEntries(fd);data.start=new Date(data.start).toISOString();data.end=new Date(data.end).toISOString();data.lat=f.dataset.online==='true'?0:Number(data.lat);data.lon=f.dataset.online==='true'?0:Number(data.lon);data.floor=data.floor===''?null:/^B\d+$/i.test(data.floor)?-Number(data.floor.slice(1)):Number(data.floor.replace(/F$/i,''));data.price_yen=data.price_yen===''?null:Number(data.price_yen);data.capacity=data.capacity===''?null:Number(data.capacity);data.booking_deadline=data.booking_deadline?new Date(data.booking_deadline).toISOString():null;data.age_min=data.age_min===''?null:Number(data.age_min);data.demo=fd.get('demo')==='on';data.preregistration=fd.get('preregistration')==='on';data.step_free=fd.get('step_free')==='on';data.elevator=fd.get('elevator')==='on';data.wheelchair=fd.get('wheelchair')==='on';data.id=f.dataset.id;data.draft_id=f.dataset.draftId||'';data.venue_rights=fd.get('venue_rights')==='on';data.indoor=fd.get('indoor')==='on';data.location_confirmed=fd.get('location_confirmed')==='on';data.completion_options=completion.eventData(f)||{};const cover=await uploadFile(await SpatialImages.file(f.elements.cover_file));if(cover)data.completion_options.cover=cover;else{const savedCover=state.drafts?.find(d=>d.id===f.dataset.draftId)?.data?.completion_options?.cover;if(savedCover)data.completion_options.cover=savedCover;}if(fd.get("remove_cover")==="on")data.completion_options.cover="";data.completion_options.cover_alt=fd.get("cover_alt")||"";eventPreview(data);}else if(type==='compose'){if(fd.get('photo')?.size&&!confirm(f.dataset.op==='post'?'この写真をイベントの公開Talkに投稿します。よろしいですか？':'この写真をトークのメンバーに送信します。よろしいですか？'))return;const photo=await uploadFile(fd.get('photo'));await mutate(f.dataset.op,{id:f.dataset.id,body:fd.get('text'),reply_to:fd.get('reply_to'),photo,photo_alt:fd.get('photo_alt')||'',share_allowed:fd.get('share_allowed')==='on',summary_consent:fd.get('summary_consent')==='on'});f.reset();f.querySelector('[data-reply-context]').hidden=true;f.querySelector('[data-photo-preview]').hidden=true;if(f.dataset.op==='post')await loadThread('event',f.dataset.id,'#cx-event-posts');else await loadThread('room',f.dataset.id,'#cx-room-thread');toast('送信しました');}}catch(err){const el=f.querySelector('[data-form-error]');if(el)el.textContent=err.message;else toast(err.message);}finally{if(button)button.disabled=false;}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.hasAttribute('data-alerts'))alertsDialog();else if(b.dataset.alertEvent){$('#cx-dialog').close();go('event',b.dataset.alertEvent);}else if(b.dataset.alertRoom){$('#cx-dialog').close();go('messages',b.dataset.alertRoom);}else if(b.dataset.ackAlert){await mutate('ack_alert',{id:b.dataset.ackAlert});render();if($('#cx-dialog').open)alertsDialog();}else if(b.hasAttribute('data-settings'))accountMenu();else if(b.hasAttribute('data-account-list'))await accountDialog();else if(b.dataset.switch){await request('/api/switch-account',{id:b.dataset.switch});$('#cx-dialog').close();await reload();toast('アカウントを切り替えました');}else if(b.hasAttribute('data-logout-all')){await request('/api/logout',{all:true});$('#cx-dialog').close();await reload();toast('この端末からログアウトしました');}else if(b.dataset.report)reportDialog(b.dataset.report,b.dataset.id);else if(b.dataset.block){if(!needLogin())return;await mutate('block',{id:b.dataset.block,active:!state.blocked?.includes(b.dataset.block)});go('people');toast('表示と接触を更新しました');}else if(b.hasAttribute('data-auth'))authDialog();else if(b.dataset.interest){if(!needLogin())return;const x=event(b.dataset.interest);if(Date.parse(x.end)<=Date.now()||x.status==='canceled')throw Error('参加受付は終了しました');if(x.my_status==='going'){go('event',x.id);return;}await mutate('rsvp',{id:x.id,status:x.my_status==='interested'?'none':'interested'});render();}else if(b.dataset.going){await toggleAttendance(b);}else if(b.dataset.bookToggle){if(!needLogin())return;const x=event(b.dataset.bookToggle);if(!x)throw Error('イベントが見つかりません');const active=x.my_booking==='none';if(!confirm(active?'無料予約またはキャンセル待ちに登録します。Joinとは別の操作です。よろしいですか？':'予約またはキャンセル待ちを取り消します。よろしいですか？'))return;const result=await mutate('book',{id:x.id,active});render();toast(result.status==='confirmed'?'予約が確定しました':result.status==='waitlisted'?'キャンセル待ちに登録しました':'予約を取り消しました');}else if(b.dataset.follow){if(!needLogin())return;await mutate('follow',{id:b.dataset.follow,active:!state.following.includes(b.dataset.follow)});render();}else if(b.dataset.editNotice)noticeEditDialog(b.dataset.eventId,b.dataset.editNotice);else if(b.hasAttribute('data-edit-profile')||b.hasAttribute('data-profile-edit'))profileDialog();else if(b.hasAttribute('data-notifications'))notificationsDialog();else if(b.hasAttribute('data-logout')){dialog('<h2>@'+esc(state.me.handle)+'からログアウト</h2><p>このアカウントのログインを終了します。別の保存済みアカウントは残ります。</p><div class="cx-actions"><button class="outline" data-cancel-logout>キャンセル</button><button class="primary" data-confirm-logout>ログアウト</button></div>');}else if(b.hasAttribute('data-cancel-logout')){$('#cx-dialog').close();}else if(b.hasAttribute('data-confirm-logout')){await request('/api/logout',{});$('#cx-dialog').close();go('home');await reload();toast('ログアウトしました');}else if(b.dataset.category)filterCards($('#cx-search')?.value||'',b.dataset.category);else if(b.hasAttribute('data-month')){const step=Number(b.dataset.month);month=step?new Date(month.getFullYear(),month.getMonth()+step,1):new Date();render();}else if(b.hasAttribute('data-new-room'))roomDialog();else if(b.dataset.dm){if(!needLogin())return;const other=account(b.dataset.dm);const r=await mutate('room',{name:other.name+'とのトーク',members:[other.id]});go('messages',r.id);}else if(b.dataset.leave){if(!confirm('退出するとこのトークの会話や写真を閲覧できなくなります。退出しますか？'))return;await mutate('leave_room',{id:b.dataset.leave});go('messages');}else if(b.dataset.muteRoom){const room=state.rooms.find(r=>r.id===b.dataset.muteRoom);await mutate('mute_room',{id:b.dataset.muteRoom,active:!room.muted});render();toast(room.muted?'通知を再開しました':'このトークの通知を止めました');}else if(b.dataset.insight){if(!needLogin())return;if(!confirm('イベント情報とあなたの興味をGoogle Cloudに送り、AIの要約・推薦理由を生成します。よろしいですか？'))return;b.disabled=true;const answer=await request('/api/insight',{id:b.dataset.insight});if($('#cx-insight'))$('#cx-insight').innerHTML=`<p>${esc(answer.summary)}</p><p>${esc(answer.reason)}</p><small class="cx-muted">${esc(answer.source)} · 主観的な提案</small>`;comment(answer.summary);b.disabled=false;}else if(b.hasAttribute("data-calendar-sync"))await SpatialCalendar.open({state:()=>state,request,dialog,esc,toast,needLogin});else if(b.dataset.google)await googleCalendar(b.dataset.google);}catch(err){b.disabled=false;toast(err.message);}});
async function googleCalendar(id){await SpatialCalendar.open({state:()=>state,request,dialog,esc,toast,needLogin},{eventId:id});}
function setupMap(){mapController=SpatialExplore.mount({getState:()=>state,esc,go,comment,propose:proposeActions,selected});}
// Poyo never issues a mutation from model text. Every screen action uses an explicit choice.
const poyo=$('#poyo-root'),bubble=$('#cx-bubble'),panel=$('#cx-poyo-panel');let speech=false,roam=true,auto=readPref('spatial-poyo-auto')==='yes',fadeTimer,hideTimer,perch=0,lastSuggestion=0,voiceEpoch=0,held=false,poyoConversation=0,poyoSending=false;const reduced=matchMedia('(prefers-reduced-motion: reduce)');
function fade(){clearTimeout(fadeTimer);clearTimeout(hideTimer);fadeTimer=setTimeout(()=>{if(bubble.matches(':hover')||bubble.contains(document.activeElement)){fade();return;}bubble.classList.add('fading');hideTimer=setTimeout(()=>bubble.hidden=true,reduced.matches?0:850)},12000);}
function poyoMessage(text,role='assistant'){const log=$('#cx-poyo-log');const last=log.lastElementChild;if(role==='assistant'&&last?.dataset.role===role&&last.textContent===text)return;const p=document.createElement('p');p.dataset.role=role;p.textContent=text;log.append(p);while(log.children.length>30)log.firstElementChild.remove();$('#cx-poyo-empty').hidden=true;log.scrollTop=log.scrollHeight;}
function resetPoyo(){poyoConversation++;poyoSending=false;voiceEpoch++;window.window.speechSynthesis?.cancel();poyo.classList.remove('poyo-talking');clearTimeout(fadeTimer);clearTimeout(hideTimer);$('#cx-poyo-log').replaceChildren();$('#cx-poyo-actions').replaceChildren();$('#cx-poyo-input').value='';$('#cx-voice-status').textContent='';$('#cx-poyo-empty').hidden=false;$('#cx-poyo-form button[type=submit]').disabled=false;bubble.hidden=true;lastSuggestion=Date.now();$('#cx-poyo-input').focus();}
$('#cx-poyo-reset').onclick=resetPoyo;
function comment(text){text=String(text);poyoMessage(text);$('#cx-bubble-text').textContent=text.length>160?text.slice(0,157)+'…':text;bubble.hidden=!panel.hidden;bubble.classList.remove('fading');fade();if(speech)say(text);}
async function say(text){const ticket=++voiceEpoch;window.window.speechSynthesis?.cancel();let voice=window.speechSynthesis?.getVoices().find(v=>v.localService&&v.lang.startsWith('ja'));if(!voice&&window.speechSynthesis){await new Promise(resolve=>{const done=()=>{clearTimeout(timer);speechSynthesis.removeEventListener('voiceschanged',done);resolve()};const timer=setTimeout(done,1500);speechSynthesis.addEventListener('voiceschanged',done,{once:true});});voice=speechSynthesis.getVoices().find(v=>v.localService&&v.lang.startsWith('ja'));}if(ticket!==voiceEpoch||!speech||document.hidden)return;if(!voice){$('#cx-voice-status').textContent='端末の日本語音声がないため、吹き出しでお知らせします。';return;}const u=new SpeechSynthesisUtterance(text.slice(0,200));u.voice=voice;u.lang='ja-JP';u.pitch=1.18;u.onstart=()=>poyo.classList.add('poyo-talking');u.onend=u.onerror=()=>poyo.classList.remove('poyo-talking');speechSynthesis.speak(u);}
function openPoyo(open){panel.hidden=!open;poyo.classList.toggle('open',open);$('#poyo-toggle').setAttribute('aria-expanded',String(open));if(open){poyo.style.transform='none';bubble.hidden=true;$('#cx-poyo-input').focus();}}
$('#poyo-toggle').onclick=()=>openPoyo(panel.hidden);$('#cx-poyo-close').onclick=()=>openPoyo(false);$('#cx-bubble-more').onclick=()=>openPoyo(true);$('#cx-bubble-close').onclick=()=>{bubble.hidden=true;clearTimeout(fadeTimer);savePref('spatial-poyo-dismissed','yes')};$('#cx-speak').onclick=()=>{speech=!speech;$('#cx-speak').textContent='発話：'+(speech?'オン':'オフ');$('#cx-speak').setAttribute('aria-pressed',String(speech));voiceEpoch++;window.window.speechSynthesis?.cancel();if(speech)say('発話をオンにしました。いつでもオフにできるよ。');};$('#cx-roam').onclick=()=>{roam=!roam;$('#cx-roam').textContent='おさんぽ：'+(roam?'オン':'オフ');$('#cx-roam').setAttribute('aria-pressed',String(roam));if(!roam)poyo.style.transform='none';};$('#cx-auto').checked=auto;$('#cx-auto').onchange=e=>{auto=e.target.checked;savePref('spatial-poyo-auto',auto?'yes':'no');savePref('spatial-poyo-dismissed','no')};$('#cx-ai').onchange=e=>aiEnabled=e.target.checked;
poyo.onpointerenter=()=>{held=true;poyo.getAnimations().forEach(a=>a.pause())};poyo.onpointerleave=()=>{held=false;poyo.getAnimations().forEach(a=>a.play())};poyo.onfocusin=()=>held=true;poyo.onfocusout=()=>held=false;
setInterval(()=>{if(!roam||reduced.matches||held||!panel.hidden||document.hidden||document.body.classList.contains('sx-ar-active'))return;perch=(perch+1)%4;const w=document.documentElement.clientWidth;const x=[0,Math.min(w*.13,150),Math.min(w*.04,60),Math.max(0,w-355)][perch],y=[0,65,Math.min(innerHeight*.28,230),90][perch];poyo.style.transform=`translate(${-x}px,${-y}px)`},18000);
function proposeActions(items){$('#cx-poyo-actions').replaceChildren();for(const [label,fn]of items){const b=document.createElement('button');b.textContent=label+' →';b.onclick=()=>{if(confirm('ぽよの提案：'+label+'。この画面操作を行いますか？')){openPoyo(false);fn()}};$('#cx-poyo-actions').append(b);}}
function proactive(){if(!completion.aiAllowed('ai_recommendation')||!auto||readPref('spatial-poyo-dismissed')==='yes'||document.hidden||Date.now()-lastSuggestion<120000||!state)return;lastSuggestion=Date.now();const chosen=(view==='event'&&event(selected)&&!event(selected).demo&&event(selected).status!=='canceled'&&Date.parse(event(selected).end)>Date.now()?event(selected):null)||[...normalEvents()].sort((a,b)=>(b.fit.score||0)-(a.fit.score||0))[0];if(view==='calendar'){comment('Joinがカレンダーに集まるよ。通知の時間も、自分のペースに合わせてみよう。');proposeActions([['Alerts設定を開く',notificationsDialog]]);}else if(chosen){comment((state.me?state.me.name+'さん、':'こんにちは、')+'「'+chosen.name+'」はどうかな。'+chosen.fit.reason+'。詳細を見て、自分に合うか決めてね。');proposeActions([['Picksの詳細を開く',()=>go('event',chosen.id)],['カレンダーを開く',()=>go('calendar')]]);}}
$('#cx-poyo-form').onsubmit=async e=>{e.preventDefault();const input=$('#cx-poyo-input'),text=input.value.trim();if(!text||poyoSending)return;const ticket=poyoConversation,submit=$('#cx-poyo-form button[type=submit]');poyoSending=true;submit.disabled=true;input.value='';poyoMessage(text,'user');$('#cx-poyo-actions').replaceChildren();try{const chosen=event(selected)||state.events.find(e=>(e.name+' '+e.description+' '+e.kind).toLowerCase().includes(text.toLowerCase()))||[...normalEvents()].sort((a,b)=>(b.fit.score||0)-(a.fit.score||0))[0];if(/予定|カレンダー/.test(text)){comment('参加予定を確認してみよう。');proposeActions([['予定を見る',()=>go('calendar')]]);}else if(chosen){if(aiEnabled&&state.me){const answer=await request('/api/insight',{id:chosen.id,query:text});if(ticket!==poyoConversation)return;comment(answer.summary+' '+answer.reason);}else comment('「'+chosen.name+'」はどうかな。'+chosen.fit.reason+'。詳しい内容も見てみてね。');if(ticket===poyoConversation)proposeActions([['体験を見る',()=>go('event',chosen.id)],['地図を見る',()=>go('map',chosen.id)]]);}else{comment('いま紹介できる開催予定はないみたい。地域や日付を変えて探してみよう。');proposeActions([['イベントを探す',()=>go('discover')]]);}}catch(err){if(ticket===poyoConversation){input.value=text;comment(err.message+'。もう一度送ってみてね。');}}finally{if(ticket===poyoConversation){poyoSending=false;submit.disabled=false;input.focus();}}};
$('#cx-mic').onclick=()=>{const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){toast('このブラウザでは音声入力を利用できません');return;}if(!confirm('音声入力を開始します。音声がブラウザ提供元の音声認識サービスへ送信される場合があります。よろしいですか？'))return;const ticket=poyoConversation,r=new Recognition();r.lang=SpatialIdentity.language();r.onresult=e=>{if(ticket!==poyoConversation)return;$('#cx-poyo-input').value=e.results[0][0].transcript;toast('内容を確認して「相談する」を押してください');};r.onerror=()=>toast('音声入力を利用できませんでした');r.start();};
const notified=new Set();let messageCounts=new Map();setInterval(()=>{if(!state?.me||document.hidden)return;const n=state.me.notifications;if(n.enabled&&completion.allowNotify('changes')){for(const e of state.events.filter(e=>e.my_status==='going')){const delta=new Date(e.start)-Date.now();if(delta>=0&&delta<=n.minutes*60000&&!notified.has(e.id)){notified.add(e.id);const t=e.name+' がまもなく始まります。';toast(t);if('Notification'in window&&Notification.permission==='granted')new Notification('Spatialの予定',{body:t});}}}if(n.messages&&completion.allowNotify('talk')){for(const r of state.rooms){if(messageCounts.has(r.id)&&r.message_count>messageCounts.get(r.id))toast(r.name+' に新しいTalkがあります');messageCounts.set(r.id,r.message_count);}}},30000);
setInterval(()=>{if(!document.hidden&&state?.me)reload(false).catch(()=>{})},60000);document.addEventListener('visibilitychange',()=>{if(document.hidden){voiceEpoch++;window.speechSynthesis?.cancel()}else proactive()});window.addEventListener('pagehide',()=>{mapController?.stop();window.speechSynthesis?.cancel()});
function readPref(k,d=''){try{return localStorage.getItem(k)||d}catch{return d}}
function savePref(k,v){try{localStorage.setItem(k,v)}catch{}}
let lastHistoryEvent='';
const historyKey=()=>state.me?'spatial-view-history:'+state.me.id:'';
function historyEntries(){try{return JSON.parse(localStorage.getItem(historyKey())||'[]').filter(x=>typeof x.id==='string'&&['event','map',undefined].includes(x.kind)).slice(0,50)}catch{return []}}
function recordHistory(id,kind='event'){if(!state.me||readPref('spatial-history-enabled')!=='yes'||!id||kind+':'+id===lastHistoryEvent)return;lastHistoryEvent=kind+':'+id;try{localStorage.setItem(historyKey(),JSON.stringify([{id,kind,at:Date.now()},...historyEntries().filter(x=>x.id!==id||x.kind!==kind)].slice(0,50)))}catch{}}
function historyDialog(){dialog(`<h2>閲覧履歴</h2><p class="cx-muted">この端末のこのアカウントにだけ保存します。初期設定はオフです。</p><label><input type="checkbox" id="cx-history-enable" ${readPref('spatial-history-enabled')==='yes'?'checked':''}> イベントとSpotsの閲覧履歴を保存</label><div class="cx-actions"><button class="outline" data-clear-history>履歴をすべて消去</button></div>${historyEntries().map(x=>`<p><a data-nav href="${route(x.kind==='map'?'map':'event',x.id)}">${x.kind==='map'?'Spot · ':''}${esc(event(x.id)?.name||'削除されたイベント')}</a> · ${esc(fmt(x.at))}</p>`).join('')||'<p>閲覧履歴はありません。</p>'}`)}
function eventMenu(id){if(!needLogin())return;const x=event(id);if(!x)return;dialog(`<h2>${esc(x.name)} · 表示設定</h2><p>この端末だけでなく、ログインした自分のFindに反映します。</p>${dismissed('event',id)?`<button class="outline" data-undo-feed="event:${esc(id)}">興味なしを取り消す</button>`:`<form class="cx-form" data-feed-dismiss="event" data-id="${esc(id)}"><label>表示を減らす理由<select name="reason"><option value="not_interested">興味がない</option><option value="irrelevant">探している内容と違う</option><option value="seen_enough">十分に見た</option><option value="other">その他</option></select></label><button class="outline">興味なし</button></form>`}<div class="cx-actions">${dismissed('host',x.owner)?`<button class="outline" data-undo-feed="host:${esc(x.owner)}">主催者の非表示を取り消す</button>`:`<button class="outline" data-hide-host="${esc(x.owner)}">この主催者を非表示</button>`}<button class="outline" data-report="event" data-id="${esc(id)}">通報</button><button class="outline" data-block-menu="${esc(x.owner)}">${state.blocked?.includes(x.owner)?'ブロック解除':'主催者をブロック'}</button></div>`)}
function hiddenFeedDialog(){dialog(`<h2>非表示にした項目</h2><p class="cx-muted">取り消すとFindやMeetに再表示されます。</p>${(state.dismissed||[]).map(x=>`<p>${esc(x.kind==='event'?event(x.id)?.name||'イベント':account(x.id)?.name||'主催者')} <button class="outline" data-undo-feed="${esc(x.kind)}:${esc(x.id)}">取り消す</button></p>`).join('')||'<p>非表示の項目はありません。</p>'}`)}
const languages={ja:'日本語',en:'English',zh:'简体中文',ko:'한국어'};
function recentEvents(){const now=Date.now();return normalEvents().filter(e=>Date.parse(e.start)<now+72*3600000).sort((a,b)=>Date.parse(a.start)-Date.parse(b.start)).slice(0,6)}
function sourceBrief(e){const notices=(e.notices||[]).filter(n=>n.at*1000>=Date.now()-72*3600000).slice(0,3);return `<article class="cx-brief-card" data-brief-id="${esc(e.id)}"><small>${esc(fmt(e.start))} · ${esc(e.place)}</small><a data-nav href="${route('event',e.id)}"><h3 data-brief-title>${esc(e.name)}</h3></a><p data-brief-summary>${esc(e.description.slice(0,200))}</p><p data-brief-notice>${esc(notices.map(n=>n.body).join(' / '))}</p><details><summary>原文を見る</summary><p>${esc(e.description)}</p>${notices.map(n=>`<p>${esc(fmt(n.at*1000))} · ${esc(n.body)}</p>`).join('')}</details></article>`}
function briefingHero(){if(!recentEvents().length)return '<section class="cx-pulse-empty"><span>近日の新しいお知らせはありません</span><a data-nav href="'+route('calendar')+'">参加予定を見る →</a></section>';return `<section class="cx-briefing" aria-label="直近イベントとお知らせ"><div class="cx-brief-head"><div><span class="cx-overline">PULSE · NEXT 72 HOURS</span><h2>この3日の体験と、お知らせ。</h2><p>開催中・72時間以内のイベントを、あなたの言葉で。</p></div><div class="cx-brief-controls" ${recentEvents().length?'':'hidden'}><label>翻訳言語<select id="cx-brief-lang">${Object.entries(languages).map(([v,n])=>`<option value="${v}" ${readPref('spatial-language','ja')===v?'selected':''}>${n}</option>`).join('')}</select></label><button class="primary" id="cx-brief-translate">AIで翻訳・要約</button><label><input type="checkbox" id="cx-brief-auto" ${readPref('spatial-brief-auto')==='yes'?'checked':''}>次回から自動翻訳</label></div></div><p id="cx-brief-status" role="status" ${recentEvents().length?'':'hidden'}>原文を表示中。AI翻訳は公開イベント・お知らせをGoogle Cloudへ送信します。</p><div class="cx-brief-grid">${recentEvents().map(sourceBrief).join('')||'<p>この3日以内のイベントはまだありません。<a data-nav href="'+route('discover')+'">Findで次回予定を探す →</a></p>'}</div></section>`}
let briefTicket=0;
function setupBriefing(){const button=$('#cx-brief-translate'),lang=$('#cx-brief-lang'),auto=$('#cx-brief-auto');if(!button)return;lang.onchange=()=>{savePref('spatial-language',lang.value);if(auto.checked)translateBriefing()};auto.onchange=()=>{savePref('spatial-brief-auto',auto.checked?'yes':'no');if(auto.checked)translateBriefing()};button.onclick=translateBriefing;if(auto.checked&&state.me)translateBriefing()}
async function translateBriefing(){if(!needLogin())return;if(!completion.aiAllowed('ai_translation')){toast('AI翻訳は設定でオフになっています');return;}const ticket=++briefTicket,renderEpoch=epoch,button=$('#cx-brief-translate'),status=$('#cx-brief-status'),language=$('#cx-brief-lang').value;if(!button)return;button.disabled=true;status.textContent='AIが翻訳・要約しています…';try{const answer=await request('/api/briefing',{language});if(ticket!==briefTicket||renderEpoch!==epoch)return;for(const item of answer.items){const card=Array.from(document.querySelectorAll('[data-brief-id]')).find(e=>e.dataset.briefId===item.id);if(!card)continue;card.querySelector('[data-brief-title]').textContent=item.title;card.querySelector('[data-brief-summary]').textContent=item.summary;card.querySelector('[data-brief-notice]').textContent=item.notice;card.lang=language}status.textContent=answer.source+' · '+languages[language]+' · 原文も確認できます。';}catch(e){if(renderEpoch===epoch)status.textContent=e.message+'（原文を表示）';}finally{if(renderEpoch===epoch)button.disabled=false}}
function qrDialog(){dialog(`<h2>SpatialのQRコード</h2><img src="/access-qr.svg" width="260" height="260" alt="Spatialを開くQRコード"><p>ログイン情報は含みません。</p><a href="/access-qr.svg" download="spatial-qr.svg">QRコードを保存</a>`)}
