 if(b.hasAttribute('data-full-settings'))settingsDialog();
 else if(b.hasAttribute('data-save-draft')){const form=b.closest('form');b.disabled=true;try{const data=Object.fromEntries(new FormData(form));for(const el of form.elements)if(el.type==='checkbox')data[el.name]=el.checked;data.completion_options=completion.eventData(form)||{};const prior=state.drafts?.find(d=>d.id===form.dataset.draftId)?.data?.completion_options||{};const cover=await uploadFile(await SpatialImages.file(form.elements.cover_file));if(cover)data.completion_options.cover=cover;else if(prior.cover)data.completion_options.cover=prior.cover;if(form.elements.remove_cover?.checked)data.completion_options.cover='';data.completion_options.cover_alt=form.elements.cover_alt?.value||'';for(const key of ['cover_file','avatar','banner_file'])delete data[key];const result=await mutate('draft_event',{id:form.dataset.draftId||'',data});go('create',result.id);toast('非公開の下書きを保存しました');}finally{b.disabled=false;}}
